window.kbPageData["views/practice/s-cabc6af5d656b214"] = {"key":"practice/s-cabc6af5d656b214","state":{"route":"practice/s-cabc6af5d656b214"},"tree":"<a data-toc-link href=\"#skills/shenlun\">申论技能首页</a><details data-branch=\"module-归纳概括\"><summary>归纳概括</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c898afc5816920c2\">概括作用与成效</a><a data-toc-link href=\"#practice/s-0b47c7faa1dcfbc7\">提炼做法与经验</a><a data-toc-link href=\"#practice/s-75a1eb1e46268fd8\">归类概括材料中的问题</a><a data-toc-link href=\"#practice/s-4863baf2b4febcf4\">配对概括做法与成效</a><a data-toc-link href=\"#practice/s-c94c813ed743298a\">从材料提取概念特征</a><a data-toc-link href=\"#practice/s-4da331cba0998f2b\">分条梳理不同立场与分歧</a></div></details><details data-branch=\"module-综合分析\"><summary>综合分析</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-43e39afd29a17e74\">解释含义与作用</a><a data-toc-link href=\"#practice/s-599008555ed60dda\">分析现象形成的原因</a><a data-toc-link href=\"#practice/s-93367fee5c934df6\">从案例推导改进建议</a></div></details><details data-branch=\"module-提出对策\"><summary>提出对策</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-c6bd983baf5dd3ae\">根据问题成因逐项提出措施</a><a data-toc-link href=\"#practice/s-ecba3f8c2c1d3b9b\">将外地经验转化为本地措施</a><a data-toc-link href=\"#practice/s-9b570af6b9f113ee\">按治理环节组织对策</a><a data-toc-link href=\"#practice/s-91888cb77ec12615\">从材料反馈中提炼改进建议</a></div></details><details data-branch=\"module-应用文写作\" open><summary>应用文写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-171ebed39b4fe1cf\">汇报与交流发言</a><a data-toc-link href=\"#practice/s-b92b682e65d12042\">面向公众动员参与</a><a data-toc-link href=\"#practice/s-cabc6af5d656b214\" aria-current=\"page\">宣传介绍与活动报道</a><a data-toc-link href=\"#practice/s-5cd530a611f08110\">编写案例摘要</a><a data-toc-link href=\"#practice/s-9f175b7eb1a79028\">陈述事由与请求</a><a data-toc-link href=\"#practice/s-38dece0b54a49be3\">拟定工作事项与措施</a><a data-toc-link href=\"#practice/s-c8dfde3ede3eadab\">撰写案例短评或点评</a></div></details><details data-branch=\"module-文章写作\"><summary>文章写作</summary><div class=\"tocChildren\"><a data-toc-link href=\"#practice/s-b8139af04b609dce\">展开分论点的论证</a><a data-toc-link href=\"#practice/s-4fdadcb77809c673\">围绕中心论点组织分论点</a><a data-toc-link href=\"#practice/s-ab43045e4cab9ffe\">从材料立意并确立中心论点</a></div></details>","packs":{"国考 2025 副省级 申论#3":"00ec7d38affb59962747e9f0","江苏 2025 A类 申论#3":"00ec7d38affb59962747e9f0","江苏 2025 C类 申论#4":"00ec7d38affb59962747e9f0"},"questions":{"国考 2025 副省级 申论#3":{"paper":"国考 2025 副省级 申论","n":3,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",2]},"江苏 2025 A类 申论#3":{"paper":"江苏 2025 A类 申论","n":3,"mod":"申论","src":["b1f59532fef09ba66d75.pdf",4],"asrc":["c5e59296c6aaf5bdf3eb.pdf",2]},"江苏 2025 C类 申论#4":{"paper":"江苏 2025 C类 申论","n":4,"mod":"申论","src":["7e3ca2d8bd92160cb8df.pdf",4],"asrc":["dcca1eb04da9373b4ee8.pdf",2]}},"first":{"qs":{"国考 2025 副省级 申论#3":{"paper":"国考 2025 副省级 申论","n":3,"mod":"申论","src":["7543a550935cd0cc16be.pdf",4],"asrc":["3f81b5d39fbc5b1d205d.pdf",2],"m":["e87c940ac57505da"],"task":"根据材料3拟写一篇不超过400字的园区入口宣传展板文稿，生动介绍今州粮仓的由来、储粮兴衰和改造后的文化新貌。","current_affairs":{"state":"否","event":null,"year":null,"basis":"作答依据是材料所述的粮仓沿革与改造案例，无需掌握窗口内的实际事件或政策部署。"},"links":[{"id":"k-85b04704b3a94ecf","label":"今州粮仓曾承担储粮重任，储粮功能弱化后转作多种小业态经营，后来一度废弃","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"answer","quote":"粮仓一度废弃多年","why":"储粮、转用和废弃构成展板需要交代的历史沿革。","origin":"逐题标记"},{"id":"k-8835ba9e1a20736c","label":"旧粮仓改造可保留建筑基本架构和典型构件，以延续历史风貌","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"老粮仓的基本架构没有改变，尽可能地保留了原貌。","why":"保留原有结构和构件解释了改造后粮仓为何仍具历史质感。","origin":"逐题标记"},{"id":"k-c0e606e4cbc51a00","label":"旧粮仓可通过沉浸式展陈和空间再利用传承粮食文化","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"为了更好地展现粮\n食文化底蕴，今州粮仓特意打造“云间麦田”展厅","why":"麦田展陈和旧仓改建后的爱粮节粮活动说明了储粮空间如何转化为文化体验空间。","origin":"逐题标记"},{"id":"s-cabc6af5d656b214","label":"按背景、历史沿革和改造现状组织场所介绍","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"先介绍了今州粮仓的背景性内容；接着主体部分从“今州粮\n仓的前世”和“今州粮仓的今生”两个方面展开","why":"需要从材料中筛选场所信息，并按历史阶段组织介绍内容，形成清晰的展板文稿。","origin":"逐题标记"}],"stem":"今州粮仓计划在园区入口处设立宣传展板。请你根据“给定资料3”，为展板拟写一篇文稿，宣传介绍粮仓的“前世\n今生”。（20分）\n要求：\n（1）紧扣资料，内容全面；\n（2）条理清晰，语言生动；\n（3）不超过400字。","options":[],"answer":"","analysis":"今州粮仓的前世今生\n  今州粮仓坐落在丛江，得名于丛江的古称“今州”，建于20世纪50年代，占地136亩。\n  新中国成立以后，今州粮仓肩负着粮食储存的重任。20世纪末，粮仓的储粮功能弱化，今州粮仓被用于多种小\n业态的经营，小业态萧条后，粮仓一度废弃多年。\n  如今，今州粮仓作为重要的历史文化资源，经过改造盘活，成为市民游客的“精神粮仓”。粮仓外部修旧如旧，沧\n桑感十足；内部蝶变重生，呈现出现代模样。雕塑巨型铁质号角传达出多元、沟通的理念；“云间麦田”展厅以唯美场\n景传递粮食文化；“吸粮房”成了临河的品茶空间；旧式粮仓更新改建成文化活动空间；标志性景观筒仓以巨幅涂鸦展\n示丛江大米航天育种的主题；文创市集汇聚优秀文创、非遗资源，搭建起优秀的市场化平台。\n  今天的今州粮仓，人文之风从巷弄中飘散而出，被凝固的旧时光在青砖红瓦间续写着新的时代故事。\n  参考答案说明：（1）本题是公文题，要求写一篇宣传类文稿，格式由“标题+正文”构成。（2）内容方面，围绕\n着“今州粮仓的‘前世今生’”这一主题，本参考答案开头部分先介绍了今州粮仓的背景性内容；接着主体部分从“今州粮\n仓的前世”和“今州粮仓的今生”两个方面展开；最后结尾部分进行了总结评价。形式方面，本参考答案做到了分段、\n分条撰写，整体上条理较为清晰。","figs":[],"state":"已标记","notes":[],"domains":["文化","公共管理"],"nature":"综合题","current":false},"江苏 2025 A类 申论#3":{"paper":"江苏 2025 A类 申论","n":3,"mod":"申论","src":["b1f59532fef09ba66d75.pdf",4],"asrc":["c5e59296c6aaf5bdf3eb.pdf",2],"m":["2ecf8fcd59bfd066"],"task":"依据给定资料6写一篇约350字的大会简讯，交代举办时间、地点和参与方，突出大会的三项亮点及其意义。","current_affairs":{"state":"是","event":"扬州市第三届大运河青年文创产业合作大会举行","year":2024,"basis":"材料6明确记载大会于2024年5月28日举行，本题要求围绕这场窗口内实际发生的大会撰写简讯。"},"links":[{"id":"k-2c9e8610df30c021","label":"扬州市第三届大运河青年文创产业合作大会举行","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"M1","quote":"2024年5月28日上午，扬州市第三届大运河青年文创产业合作大会在扬州广陵公共文化中心举行。","why":"大会是简讯的报道对象，举办时间和地点是开头的基本信息。","origin":"逐题标记"},{"id":"k-1bf3c0c29509a2ac","label":"知识产权服务通过保护创作者权益促进文创创新","catalog_id":null,"type":"原理与机制","role":"直接考查","field":"M1","quote":"益，激发他们的创作热情，推动文创产业的持续创新。","why":"材料以发布版权服务平台为例，说明权益保护如何激发创作并促进持续创新。","origin":"逐题标记"},{"id":"k-66c8d4e83c6dd4d4","label":"扬州大运河青年文创展厅授牌与产学研融合的地方发展意义","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"通过产学研的深度融合，为扬州经济发展注入新的活力。","why":"参考答案将展厅授牌列为大会亮点，并以产学研融合说明其对地方经济的意义。","origin":"逐题标记"},{"id":"k-2fbfba807bb9a3d8","label":"跨校跨学科工作坊以应用场景开展用户体验设计实践","catalog_id":null,"type":"事实与事件","role":"直接考查","field":"M1","quote":"学生设计实践，聚焦文旅、交通、健康医疗、智慧服务、社区邻里、低碳产业等场景塑造","why":"材料给出的实践方式和应用场景说明了研究生工作坊揭牌的具体内容。","origin":"逐题标记"},{"id":"s-cabc6af5d656b214","label":"提取活动基本要素并分条概括亮点及意义","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"要素齐全，突出亮点、意义，条理清楚。","why":"需要把分散的活动信息整理为开头要素，并将每项亮点与其作用对应写入正文。","origin":"逐题标记","originalId":"s-a3163a185d5b3ed5"}],"stem":"请就“给定资料6”中“扬州市第三届大运河青年文创产业合作大会”的举行，写一则简讯。（20分）\n要求：要素齐全，突出亮点、意义，条理清楚。篇幅350字左右。","options":[],"answer":"","analysis":"扬州市第三届大运河青年文创产业合作大会胜利召开\n  2024年5月28日上午，扬州市第三届大运河青年文创产业合作大会在扬州广陵公共文化中心举行。来自扬州市青\n商会的青年创客，以及相关院校、企业、产业基金的嘉宾们相聚在京杭大运河畔共谋发展。\n  大会亮点纷呈。首先，发布了大运河青澜文创湾知识产权（版权）服务平台，旨在保护创作者权益，激发创作\n热情，推动文创产业持续创新。此外，扬州市大运河青年文创展厅授牌仪式也顺利举行，通过产学研深度融合，为\n扬州经济注入新活力。大会现场还为“行走扬州城：文创产品设计与体验研究生工作坊”项目揭牌，该项目系广陵区与\n省内外多所院校联合实施，集结多学科领域的学生设计实践，聚焦多个场景，探讨用户体验设计的创新方法和实践\n路径。\n  此次大会促进了扬州青年文创人才的交流与合作，一幅新时代的《清明上河图》正徐徐展开。\n  参考答案说明：（1）格式方面，本参考答案写到了“标题”“正文”两个部分。（2）正文部分，一方面从内容上来\n看，围绕“扬州市第三届大运河青年文创产业合作大会”这一主题，本参考答案的开头先介绍了此次大会举办的背景；\n主体部分介绍了此次大会的三个亮点及意义；结尾进行了总结。另一方面，形式上，本参考答案做到了分段、分条\n撰写，整体上条理较为清晰。","figs":[],"state":"已标记","notes":[],"domains":["文化","经济"],"nature":"综合题","current":true},"江苏 2025 C类 申论#4":{"paper":"江苏 2025 C类 申论","n":4,"mod":"申论","src":["7e3ca2d8bd92160cb8df.pdf",4],"asrc":["dcca1eb04da9373b4ee8.pdf",2],"m":["d893167395ce01a8"],"task":"以戴窑镇政府工作人员的身份，依据材料7自拟标题，为兴化市政府网站“今日兴化”栏目撰写一篇约1000字的宣传稿，集中呈现戴窑镇稻米产业的特色与成效。","current_affairs":{"state":"否","event":null,"year":null,"basis":"题目要求依据材料提炼产业特色，材料中的入选名单和品牌榜单是可选用的产业成效例证。"},"links":[{"id":"k-d08306ba8e76fafd","label":"地方水土禀赋和稻米品质支撑地理标志品牌建设","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"answer","quote":"依托优越水土条件，培育出","why":"参考稿以戴窑的水土优势和兴化大米的品质说明地方品牌的形成基础。","origin":"逐题标记"},{"id":"k-118c544df1d44437","label":"校地共建和智慧稻作技术推广促进稻米增产提质","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"建立适宜兴化的智慧稻作模式","why":"材料以校地共建、栽培技术推广和试验区成效说明科技如何改善稻米产量与品质。","origin":"逐题标记"},{"id":"k-5facd10c57465db7","label":"农村交通改善和土地流转为新农人规模种植创造条件","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"借着村里土地流转的机会，他包下了600亩农田，开始新农人之路","why":"小马哥的经历串联了道路桥梁改善、土地流转和规模经营，说明新农人进入稻米生产的条件。","origin":"逐题标记"},{"id":"k-2d8bbc68e8ab0503","label":"行业协会以标准引导稻米精深加工，产业集聚衔接生产、加工和贸易","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"制定大米行业标准和质量安全标准","why":"材料将协会制定标准、企业加工升级和“米企一条街”的产加销集聚作为全产业链发展的具体表现。","origin":"逐题标记"},{"id":"k-cdb2446778680ce0","label":"网络货运平台按需补充运力，降低稻米旺季运输成本","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"由于旺季时的短期运输需求激增，使用平台是一件省时又省钱","why":"万家福米业的案例说明，销售范围扩大后，平台可以补充常用车辆的运力，应对旺季短期运输需求。","origin":"逐题标记"},{"id":"k-9b00ee5a077b63a2","label":"稻米文化展示扩大产业影响并增强乡村居民认同","catalog_id":null,"type":"观点与论证","role":"直接考查","field":"M1","quote":"展示稻米种植加工的历史和文化，提升粮食市场影响力","why":"材料以稻米文化展览馆说明产业发展与文化传承相结合的做法，并指出其对市场影响力和居民归属感的作用。","origin":"逐题标记"},{"id":"s-cabc6af5d656b214","label":"围绕指定对象筛选并归类产业特色","catalog_id":null,"type":null,"role":"直接考查","field":"question","quote":"请围绕戴窑镇稻米产业特色","why":"题目限定了宣传对象，写作需从兴化市层面和戴窑镇层面的叙述中选取相关信息，并按产业特色归类。","origin":"逐题标记","originalId":"s-e4c3dfa0f0d05dfb","additionalEvidence":[{"id":"s-6d8337b1f5e0e9bc","label":"用段首主旨句统领做法、案例和成效","catalog_id":null,"type":null,"role":"解题依据","field":"answer","quote":"在具体内容的展开上主要采用了讲道理和举例子的方式","why":"参考稿先概括数字物流的作用，再用万家福米业调配旺季运力的做法和成效支撑段落主旨。","origin":"逐题标记"}]}],"stem":"假如你是“给定资料7”中戴窑镇政府机关的一名工作人员，请围绕戴窑镇稻米产业特色，给兴化市政府网站“今日\n兴化”栏目写一篇宣传稿。（40分）\n要求：\n（1）结合给定资料，自选角度，自拟标题；\n（2）内容充实，结构完整；\n（3）篇幅1000字左右。","options":[],"answer":"","analysis":"“稻”梦戴窑，“香”约兴化\n    戴窑镇地处江淮腹部，河网交织、土地肥沃，坐拥“鱼米之乡”天然禀赋，是兴化大米主产区。戴窑镇牢记“粮食\n也要打出品牌”重要指示，紧扣“水韵苏米”建设，依托优越水土条件，培育出稻谷金黄、晶莹透亮、米粒饱满、柔软\n油润、口感特佳的国家地理标志产品。近年更构建起全产业链发展模式，让水乡米香飘向四方。\n    科技赋能，智慧田野生出“金稻穗”。兴化市与国内知名农业大学共建，建立智慧稻作模式，推广先进的水稻机\n插缓混一次施肥技术和绿色防控技术。建成江苏省水稻项目核心试验区，实现每公顷1.22万公斤的全国最高单产，\n品种更优、品质更高。2023年，兴化市入选首批“全国农业科技现代化先行县”，戴窑镇功不可没，年粮食总产量已逾\n25亿斤，粮食加工企业实现工业总产值141.83亿元。\n    贤人辈出，新农人激活“田间新活力”。曾经，戴窑镇交通不便，种地辛苦，年轻人纷纷外出。如今，村里道路\n设施日益完善，一批像小马哥这样的新农人选择返乡创业。他们包下大片农田，积极学习数字化种植技术，用新理\n念、新技术武装头脑，成为戴窑镇粮食生产的主力军。\n\n  标准领航，全链打造“产业新高地”。戴窑镇成立技术行业协会，制定行业标准和质量安全标准，引导企业向精\n深加工升级。目前，镇内有大米加工企业52家，年加工能力700万吨，产品畅销多个地区。国家级、省级、市级龙头\n企业齐聚，“贤人”“板桥”等众多著名品牌熠熠生辉，形成了集原粮生产、稻米加工、贸易于一体的粮食市场和产业集\n中区“米企一条街”。\n  平台增效，数字物流畅通“全国大市场”。随着销售半径扩大，戴窑镇米企以数字物流破局运输难题。农业产业\n化国家级重点龙头企业万家福米业便是典型代表：企业配备两条日加工600吨的自动化精米加工流水线，拥有11.035\n万吨标准粮食低温仓容。每年销售旺季，通过网络平台高效调配运力，降本增效。其明星产品“老娘舅”稻香米年销量\n超6万吨，“光明”“粒粒源”等品牌大米畅销全国。\n  文化铸魂，稻作文明孕育“振兴同心圆”。兴化推动产业与文化融合，建立稻米文化展览馆，展示稻米种植加工\n历史文化。2024年9月22日，“兴化大米”入选国际稻米品牌百强榜。独具风格的稻米文化带动经济发展，提升乡村审\n美，增强居民认同感和归属感，促进社会和谐，推动治理水平不断提升。\n  从田间到餐桌，从传统到现代，戴窑镇正以稻米产业为核心，在多方协同推动下，不断书写乡村振兴的新篇\n章，让兴化大米的品牌更加响亮，让这片鱼米之乡焕发出新的生机与活力。\n文章分析\n                      “稻”梦戴窑，“香”约兴化\n  【标题的优点：一方面，在内容上，标题突出了主题；另一方面，在形式上，采用对城市结构，颇有亮点。】\n  （1）戴窑镇地处江淮腹部，河网交织、土地肥沃，坐拥“鱼米之乡”天然禀赋，是兴化大米主产区。（2）戴窑镇\n牢记“粮食也要打出品牌”重要指示，紧扣“水韵苏米”建设，依托优越水土条件，培育出稻谷金黄、晶莹透亮、米粒饱\n满、柔软油润、口感特佳的国家地理标志产品。近年更构建起全产业链发展模式，让水乡米香飘向四方。\n  【开头的优点：★内容方面。宣传稿的开头首先介绍了戴窑镇优越的水土条件，是兴化大米的主产区；其次，\n介绍了戴窑镇稻米产业发展的总体情况。★文字表达方面。衔接流畅，富有文采。】\n  科技赋能，智慧田野生出“金稻穗”。（1）兴化市与国内知名农业大学共建，建立智慧稻作模式，推广先进的水\n稻机插缓混一次施肥技术和绿色防控技术。（2）建成江苏省水稻项目核心试验区，实现每公顷1.22万公斤的全国最\n高单产，品种更优、品质更高。（3）2023年，兴化市入选首批“全国农业科技现代化先行县”，戴窑镇功不可没，年\n粮食总产量已逾25亿斤，粮食加工企业实现工业总产值141.83亿元。\n  【主体部分1的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“科技赋能”这一\n方面展开论述的。★具体展开：（1）指出兴化市与农业大学共建，建立智慧稻作模式；（2）介绍了通过建成江苏\n省水稻项目核心试验区，实现增产提质；（3）强调了兴化市通过现代科技推动农业发展的成果。注意：以上三个方\n面的内容都是紧扣“科技赋能，智慧田野生出‘金稻穗’”这个核心句进行分析论述的，具体展开的内容针对性强，层次\n丰富。在具体内容的展开上主要采用了讲道理、列数字的论证方式，论述清晰透彻。】\n  贤人辈出，新农人激活“田间新活力”。（1）曾经，戴窑镇交通不便，种地辛苦，年轻人纷纷外出。（2）如\n今，村里道路设施日益完善，一批像小马哥这样的新农人选择返乡创业。（3）他们包下大片农田，积极学习数字化\n种植技术，用新理念、新技术武装头脑，成为戴窑镇粮食生产的主力军。\n  【主体部分2的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“新农人激活‘田\n间新活力’”这一方面展开论述的。★具体展开：（1）先指出过去戴窑镇交通不便，年轻人不愿种地；（2）接着介绍\n现在道路设施完善，新农人返乡创业；（3）新农人通过学习新技术、新理念，成为粮食生产主力军。注意：以上三\n个方面的内容都是紧扣“贤人辈出，新农人激活‘田间新活力’”这个核心句进行分析论述的，具体展开的内容针对性\n强，层次丰富。在具体内容的展开上主要采用了讲道理的方式，论述清晰有力。】\n  标准领航，全链打造“产业新高地”。（1）戴窑镇成立技术行业协会，制定行业标准和质量安全标准，引导企业\n向精深加工升级。（2）目前，镇内有大米加工企业52家，年加工能力700万吨，产品畅销多个地区。国家级、省\n级、市级龙头企业齐聚，“贤人”“板桥”等众多著名品牌熠熠生辉，形成了集原粮生产、稻米加工、贸易于一体的粮食\n市场和产业集中区“米企一条街”。\n  【主体部分3的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“标准领航，引\n导产业升级”这一方面展开论述的。★具体展开：（1）先介绍了戴窑镇成立技术行业协会，制定标准，引导企业升\n级；（2）接着指出戴窑镇汇聚众多大米加工企业，形成粮食市场和产业集中区“米企一条街”。注意：以上两个方面\n的内容都是紧扣“标准领航，全链打造‘产业新高地’”这个核心句进行分析论述的，具体展开的内容针对性强，层次丰\n富。在具体内容的展开上主要采用了讲道理、列数字的论证方式，论述清晰深刻。】\n  平台增效，数字物流畅通“全国大市场”。（1）随着销售半径扩大，戴窑镇米企以数字物流破局运输难题。\n（2）农业产业化国家级重点龙头企业万家福米业便是典型代表：企业配备两条日加工600吨的自动化精米加工流水\n\n线，拥有11.035万吨标准粮食低温仓容。每年销售旺季，通过网络平台高效调配运力，降本增效。其明星产品“老娘\n舅”稻香米年销量超6万吨，“光明”“粒粒源”等品牌大米畅销全国。\n  【主体部分4的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“数字物流助力\n市场畅通”这一方面展开论述的。★具体展开：（1）先介绍了戴窑镇米企通过数字物流破解运输难题；（2）接着介\n绍了万家福米业通过网络平台调配运力，降本增效的典型案例。注意：以上两个方面的内容都是紧扣“平台增效，数\n字物流畅通‘全国大市场’”这个核心句进行分析论述的，具体展开的内容针对性强，层次丰富。在具体内容的展开上主\n要采用了讲道理和举例子的方式，论述充实深刻。】\n  文化铸魂，稻作文明孕育“振兴同心圆”。（1）兴化推动产业与文化融合，建立稻米文化展览馆，展示稻米种植\n加工历史文化。（2）2024年9月22日，“兴化大米”入选国际稻米品牌百强榜。（3）独具风格的稻米文化带动经济发\n展，提升乡村审美，增强居民认同感和归属感，促进社会和谐，推动治理水平不断提升。\n  【主体部分5的优点：★核心句：宣传稿的核心句是紧扣“戴窑镇稻米产业特色”这一主题提出的。形式上，它在\n段首处直接写出，位置突出，容易发现。内容上，关键词突出，内容要点明确，可以明显看出它是从“稻米产业与文\n化结合”这一方面展开论述的。★具体展开：（1）先介绍了兴化市推动产业与文化融合，建立稻米文化展览馆；\n（2）接着指出“兴化大米”入选国际稻米品牌百强榜；（3）最后，阐述了稻米文化的重要作用。注意：以上三个方面\n的内容都是紧扣“文化铸魂，稻作文明孕育‘振兴同心圆’”这个核心句进行分析论述的，具体展开的内容针对性强，层\n次丰富。在具体内容的展开上主要采用了讲道理的方式，论述清晰透彻。】\n  从田间到餐桌，从传统到现代，戴窑镇正以稻米产业为核心，在多方协同推动下，不断书写乡村振兴的新篇\n章，让兴化大米的品牌更加响亮，让这片鱼米之乡焕发出新的生机与活力。\n  【结尾的优点：宣传稿的结尾回扣了“戴窑镇稻米产业特色”这一主题，并进行了总结展望。】","figs":[],"state":"已标记","notes":[],"domains":["经济","科技","文化"],"nature":"综合题","current":false}},"materialFiles":{"e87c940ac57505da":"31d1ee3736324baa1e2f224c","2ecf8fcd59bfd066":"38e18c656eb0e51e1cb8fe49","d893167395ce01a8":"7b2f4f342457b49963f5bb6d"},"terms":{"k-85b04704b3a94ecf":{"id":"k-85b04704b3a94ecf","mode":"k","type":"事实与事件","title":"今州粮仓的历史沿革","qs":[],"count":1},"k-8835ba9e1a20736c":{"id":"k-8835ba9e1a20736c","mode":"k","type":"观点与论证","title":"今州粮仓修旧如旧","qs":[],"count":1},"k-c0e606e4cbc51a00":{"id":"k-c0e606e4cbc51a00","mode":"k","type":"事实与事件","title":"今州粮仓的粮食文化传承","qs":[],"count":1},"s-cabc6af5d656b214":{"id":"s-cabc6af5d656b214","mode":"s","type":"应用文写作","title":"宣传介绍与活动报道","qs":[],"count":3},"k-2c9e8610df30c021":{"id":"k-2c9e8610df30c021","mode":"k","type":"事实与事件","title":"扬州市第三届大运河青年文创产业合作大会","qs":[],"count":1},"k-1bf3c0c29509a2ac":{"id":"k-1bf3c0c29509a2ac","mode":"k","type":"原理与机制","title":"知识产权服务促进文创创新","qs":[],"count":1},"k-66c8d4e83c6dd4d4":{"id":"k-66c8d4e83c6dd4d4","mode":"k","type":"事实与事件","title":"扬州市大运河青年文创展厅授牌","qs":[],"count":1},"k-2fbfba807bb9a3d8":{"id":"k-2fbfba807bb9a3d8","mode":"k","type":"事实与事件","title":"“行走扬州城：文创产品设计与体验研究生工作坊”启动","qs":[],"count":1},"k-d08306ba8e76fafd":{"id":"k-d08306ba8e76fafd","mode":"k","type":"事实与事件","title":"兴化大米的产地与品质","qs":[],"count":1},"k-118c544df1d44437":{"id":"k-118c544df1d44437","mode":"k","type":"原理与机制","title":"兴化智慧稻作","qs":[],"count":1},"k-5facd10c57465db7":{"id":"k-5facd10c57465db7","mode":"k","type":"原理与机制","title":"戴窑新农人的规模种植","qs":[],"count":1},"k-2d8bbc68e8ab0503":{"id":"k-2d8bbc68e8ab0503","mode":"k","type":"原理与机制","title":"戴窑稻米加工标准与产业集聚","qs":[],"count":1},"k-cdb2446778680ce0":{"id":"k-cdb2446778680ce0","mode":"k","type":"原理与机制","title":"网络平台补充稻米旺季运力","qs":[],"count":1},"k-9b00ee5a077b63a2":{"id":"k-9b00ee5a077b63a2","mode":"k","type":"观点与论证","title":"兴化稻米文化传承与产业发展","qs":[],"count":1}},"questions":{}},"firstMaterials":[{"key":"e87c940ac57505da","value":["材料3","材料3\n   历史上的丛江，米业兴旺、漕舟云集，粮食存储自古有之。明朝起，丛江就是长江下游一带主要的粮食集散地\n之一，具有独特的粮食文化。\n   20世纪50年代，占地面积136亩的今州粮仓在此落成。丛江古称今州，今州粮仓由此得名。粮仓傍运河、临良\n田，粮食及与粮食有关的营生就成为这里长久以来的支柱产业。新中国成立以后，这里就承担着粮食储存的重任。\n今州粮仓作为丛江粮食文化的重要“见证者”，保留了诸多历史记忆。曾经在粮仓工作过的老王指着老照片回忆\n道：“粮食问题关系着生存问题，粮食的保管至关重要。当时能在粮仓工作，是非常光荣的。我们那个时候技术落\n后，交粮、搬运、收发货全凭体力。夏天浑身汗，冬天满身霜，叉袋扁担加栲栳，肩挑背负走高跳，这就是最真实\n的写照。”\n   20世纪末，粮仓的储粮功能逐渐弱化，衰落的步伐不断加速。后来，粮仓被分给100多个小业主，一个大粮仓里\n混杂着五金、仓储、广告等好几种业态，经营混乱驳杂。再后来，这些小业态也萧条了。\n   今州粮仓虽废弃多年，所幸，那些几乎与新中国同龄的“万担仓”被完好地保留了下来，它们是重要的历史文化资\n源，也有着很大的改造空间。\n   “当初进来时，这里满眼凄凉与荒疏。”今州粮仓园区负责人老金描述起当时的情景，“空落落的院子里，杂草从\n水泥地面缝隙钻出。建筑内部，各种箱子、架子、隔板东倚西躺，还有东拖西拉的绳索、电线，以及瓜皮帽样的白\n炽灯、低低下垂的吊扇等，显得凌乱不堪。”如何通过改造让破败的老粮仓“苏醒”，成为园区改造项目组面临的难\n题。\n\n  大家最初想在粮仓屋顶上搭建可以漫步的云廊。听起来很浪漫，但是设计师不建议这样做。“粮仓才是整个项目\n的主题和背景，应该保留原来那些朴素的东西。”项目组最后决定不加云廊，而是突出老粮仓屋顶上的青瓦、红瓦，\n这样，从空中往下看，也颇有味道。\n  “老粮仓的基本架构没有改变，尽可能地保留了原貌。”老金说。当年粮仓的墙面依旧沧桑斑驳，墙上的白灰剥脱\n后透出亮眼的红，也无须填补。粮仓内部也一样，桁条依旧是那根桁条，立柱也依旧瘦削颀长，照明的灯罩还是瓜\n皮帽的模样，只是灯泡已换成环保低耗的产品。\n  如今，百年粮仓修旧如旧，外部依旧沧桑感十足，内部却蝶变重生，呈现出一幅现代模样。\n  步入改造后的今州粮仓园区，映入眼帘的一大片空地是以前的晒谷场，旷远疏阔，视野很好。现在，这里矗立\n着一个造型独特的雕塑——巨型铁质号角，蕴含着表达诉求、为不同群体发声的意义，传达出多元、沟通的理念。\n  “远处蔚蓝天空下，涌动着金色的麦浪……”一首歌曲让人们仿佛看到翻涌的金黄在麦田间姿态万千。而今州粮仓\n就将这“金色麦田”搬了进来。曾经，无数的稻穗在这里成为米粒，无数的麦子在这里被磨成面粉。为了更好地展现粮\n食文化底蕴，今州粮仓特意打造“云间麦田”展厅，让人们得以通过唯美的场景感悟粮食文化。整个展厅都是一簇簇金\n黄的麦穗，游客低头就能闻到麦香。扎实的草垛错落地藏在麦田里，游客抬头就能看见展厅里特意布置的棉花云，\n沉浸式感受浓浓的丰收气息。\n  如今，虽然粮仓的功能与从前不同了，但是粮食文化作为精神食粮将一直保留。昔日农民用来交粮的“吸粮房”，\n摇身一变成了临河的品茶空间，可供游人伴着清雅音乐闻香品茗；今州粮仓现存数十座完好的旧式粮仓，经过更新\n改建，有的做了画室，有的变身剧场或展馆，沉浸式演出、画展、爱粮节粮主题日等活动在这里陆续举办；高24\n米、直径5.5米的标志性景观——筒仓，现在披上了巨幅涂鸦《稻田守望者》——宇航员行走在稻田中，手持水稻，\n仰望星空，表现了丛江大米航天育种的主题。\n  在这里，人们除了能触摸到老粮仓的文化历史，还能翻开更多的丛江历史。“丛江自宋代以来便有市集，诞生时\n间早、规模大。”老金介绍说，“园区特意策划了文创市集，汇聚当地及周边地区的优秀文创、非遗资源，搭建起了更\n多优秀的市场化平台。”\n  人文之风从巷弄中飘散而出，被凝固的旧时光在青砖红瓦间开始续写时代故事。今州粮仓好比一个精美的花\n园，不仅吸引了名人艺术家纷纷入驻，也吸引了更多的游人前来品茗看展，这里已经成为深受市民游客喜爱的“精神\n粮仓”。",["7543a550935cd0cc16be.pdf",2]],"label":"国考 2025 副省级 申论|材料3"}],"node":{"id":"s-cabc6af5d656b214","mode":"s","title":"宣传介绍与活动报道","type":"应用文写作","domain":"文化","reading":"","intro":"","priority":100,"aliases":["按背景、历史沿革和改造现状组织场所介绍","围绕指定对象筛选并归类产业特色","用段首主旨句统领做法、案例和成效","提取活动基本要素并分条概括亮点及意义","撰写展板与宣传稿","提炼活动亮点，撰写简讯"],"qs":["国考 2025 副省级 申论#3","江苏 2025 A类 申论#3","江苏 2025 C类 申论#4"],"current":true,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"method":"先交代对象或活动的基本事实，再挑出有代表性的亮点和作用，按文种组织正文。","subject":"申论","publishedSets":[{"name":"宣传介绍与活动报道","ids":["国考 2025 副省级 申论#3","江苏 2025 A类 申论#3","江苏 2025 C类 申论#4"],"units":[["国考 2025 副省级 申论#3"],["江苏 2025 A类 申论#3"],["江苏 2025 C类 申论#4"]]}]}};
